    ["Issued by %@", "Издатель: %@", "Veren: %@"],
    ["No", "Нет", "Hayır"],
    ["No GOST certificates", "Нет сертификатов ГОСТ", "GOST sertifikası yok"],
    ["No key containers (insert the token)", "Нет ключевых контейнеров (подключите токен)", "Anahtar kapsayıcısı yok (token'ı takın)"],
