    ["None", "Нет", "Yok"],
    ["OGRN %@", "ОГРН %@", "OGRN %@"],
    ["Open cryptopro.ru", "Открыть cryptopro.ru", "cryptopro.ru'yu Aç"],
    ["Optional: TSA URL for CAdES-T", "Необязательно: адрес TSA для CAdES-T", "İsteğe bağlı: CAdES-T için TSA adresi"],
    ["Organisation INN %@", "ИНН организации %@", "Kuruluş INN %@"],
    ["PIN:", "PIN:", "PIN:"],
    ["Power of attorney (МЧД)", "Доверенность (МЧД)", "Vekâletname (МЧД)"],
    ["Power of attorney (МЧД):", "Доверенность (МЧД):", "Vekâletname (МЧД):"],
    ["Power of attorney № %@ (%@)", "Доверенность № %@ (%@)", "Vekâletname № %@ (%@)"],
